// The Forgotten Rhythm — Friday 6 and Saturday 7 September (docs/BIBLE.md 644–705). Ids: name_day_nnn, the hundreds are
// the bible's scene (fri_1xx = F1 … sat_14xx = S14; fri_0xx / sat_0xx are the morning, the looks and the hints).
Object.assign(window.LINES, {
  // ================================================================ FRIDAY: the morning
  narr_fri_001: ['narr', 'Friday. The fan in room 4 turned all night and moved nothing but the heat.'],
  alan_fri_002: ['alan', '[sits up] Somebody\'s running on the stones outside. Nobody runs in this heat unless something has happened.'],
  vasco_fri_003: ['vasco', '[into the pillow] Then let it happen without us for ten more minutes.'],
  narr_fri_004: ['narr', 'In the kitchen the radio was louder than usual, and Señora Mireya was not wiping the table.'],
  radio_fri_005: ['radio', '[crackle] …Tropical Storm Hortense, strengthening… and in the Zona Colonial, the night watchman of the Parque Colón found this morning…'],
  mireya_fri_006: ['mireya', '[turns the radio down] Don Eusebio. Thirty years he watched that cathedral. Thirty years, and he never fell asleep once.'],
  alan_fri_007: ['alan', 'Found how?'],
  mireya_fri_008: ['mireya', '[over her glasses] Wet, señor. In the park. It hasn\'t rained for nine days. [pause] Eat. Then go and look, because you will anyway.'],
  mireya_fri_009: ['mireya', 'And mark my chart before you go. Hortense. The radio says where she is. I am too old to stand on a chair.'],
  mireya_fri_010: ['mireya', 'Tobías was in at six for coffee. He goes up every night to dry her, the bell. He looked like he hadn\'t slept since April.'],
  alan_fri_011: ['alan', 'He dries the bell. Every night.'],
  mireya_fri_012: ['mireya', 'Every night. Like you dry a child. [pause] Eat your mangú.'],
  radio_4: ['radio', '…Tropical Storm Hortense, fifteen point eight north, sixty west, east of the Leeward Islands, strengthening…'],
  radio_5: ['radio', '…Hurricane Hortense, category one, sixteen point one north, sixty-two west. Categoría uno. Por ahora…'],
  alan_fri_look_radio: ['alan', 'The radio. It\'s on a first-name basis with the hurricane.'],
  alan_fri_look_chart: ['alan', 'Mireya\'s hurricane chart, from the Listín Diario. Pins in it like a voodoo doll. A Catholic voodoo doll.'],
  alan_fri_chart_done: ['alan', 'Today\'s pin is in. Hortense is creeping west. Towards us. Everything is creeping towards us this week.'],
  alan_fri_need_chart: ['alan', 'Mireya wants today\'s pin on the chart first. I wouldn\'t cross her before ten in the morning.'],
  mireya_fri_look: ['alan', 'Señora Mireya. She can see through walls, and through me, which is thinner.'],
  mireya_fri_talk: ['mireya', 'The park, señor. Go. And come back for lunch, or don\'t, but tell me which.'],
  // ================================================================ F1: Parque Colón, the watchman
  narr_fri_101: ['narr', 'The square was grey under a sky that would not rain. Something lay by the fountain under a blanket, and a sergeant stood over it as if he had been told to wait for it to explain itself.'],
  alan_fri_102: ['alan', 'He\'s been there all night. Look at the stones.'],
  batista_fri_103: ['batista', '[the toothpick moves to the other side] Tourist.'],
  alan_fri_104: ['alan', 'Bookseller. Sanches. I\'m staying on Las Damas.'],
  batista_fri_105: ['batista', 'Sargento Batista. Don\'t touch him. Look, if you like. Everybody else is looking.'],
  batista_fri_106: ['batista', 'Tell me what you see. Not what you think. What you see.'],
  alan_fri_look_watchman: ['alan', 'An old man under a grey blanket. His boots are polished. Someone loved him or he loved his boots.'],
  alan_fri_obs_trousers: ['alan', 'His trousers are soaked to the waist. Not damp. Soaked.'],
  batista_fri_obs_trousers: ['batista', '[writes] Soaked. Yes.'],
  alan_fri_obs_puddle: ['alan', 'That puddle by the fountain is salt. You can see the rim drying white.'],
  batista_fri_obs_puddle: ['batista', '[crouches, touches, tastes his finger, spits] Salt. Bueno.'],
  alan_fri_obs_band: ['alan', 'And there: a wet band, across the whole square, from the fountain to the cathedral steps. It stops in a straight line. Water doesn\'t stop in a straight line.'],
  batista_fri_obs_band: ['batista', '[looks a long time] No. It doesn\'t.'],
  alan_fri_obs_fish: ['alan', 'There\'s a fish by his boot. It\'s alive. It\'s still alive.'],
  batista_fri_obs_fish: ['batista', '[picks it up by the tail; it flips] Usted lo vio. You saw it. Now I have a witness who is not me.'],
  alan_fri_obs_bench: ['alan', 'A bench. Dry. Everything above the line is dry.'],
  batista_fri_obs_wrong: ['batista', '[the toothpick doesn\'t move] That\'s what you think. I asked what you see.'],
  batista_fri_107: ['batista', 'Four things. Four. Most people see a drunk who fell in the fountain. [pause] And you\'re not surprised.'],
  alan_fri_108: ['alan', 'I\'ve seen water where it shouldn\'t be before. In Lisbon.'],
  batista_fri_109: ['batista', 'Then you\'ll stay where I can find you. I\'m not asking, I\'m telling.'],
  narr_fri_110: ['narr', 'At the edge of the crowd a heavy man in a grey suit was talking quietly to two of the uniformed police, his hands in his pockets, as if the heat had been arranged for other people.'],
  narr_fri_111: ['narr', 'Batista saw him and spat his toothpick onto the stones.'],
  alan_fri_112: ['alan', 'Who\'s that?'],
  batista_fri_113: ['batista', 'Nobody. A retired colonel. [pause] Nobody who should be at a drowning.'],
  narr_fri_114: ['narr', 'Then the bishop came out of the cathedral, walked straight into the puddle in his good shoes, and knelt.'],
  bishop_fri_115: ['bishop', '[to the crowd, warm, carrying] This is a holy place. Whatever was done here, we will answer it with something that is ours, not theirs.'],
  alan_fri_116: ['alan', '"Not theirs." Whose, then?'],
  narr_fri_117: ['narr', 'Across the roof of the bishop\'s black car the driver was looking at the blanket. Lean, a fresh haircut, polished shoes he kept wiping on the back of his calf. Alan had seen that face on a step in a dark alley, two nights ago, saying "what the hell do you want".'],
  alan_fri_118: ['alan', 'The young man from Tata\'s alley. He drives the bishop. [pause] He\'s her grandson. He has her eyes in the photograph.'],
  alan_fri_note_band: ['alan', 'Two wet bands now. I should write that down before I convince myself I imagined them.'],
  alan_fri_look_cathedral: ['alan', 'The Primada. First cathedral in the Americas. Today it looks like it would like to be left out of this.'],
  alan_fri_look_statue: ['alan', 'Columbus, pointing. Pointing is how all this started.'],
  alan_fri_look_bishopcar: ['alan', 'The bishop\'s black car. The driver polishes it like it owes him money.'],
  alan_fri_look_ballplayers: ['alan', 'No ballplayers this morning. Even the boys with gloves have gone home.'],
  alan_fri_park_done: ['alan', 'The watchman\'s gone. Only the line on the stones is left, and it\'s drying.'],
  // ================================================================ F2: El Conde, the coconut sweet
  narr_fri_201: ['narr', 'El Conde smelled of fried dough and diesel. Halfway down, a woman sat behind a tray of sweets under a lace cloth, fanning the flies with a folded lottery ticket.'],
  alan_fri_202: ['alan', 'Moncho won\'t talk to a tourist. He might take something from his grandmother\'s kitchen.'],
  alan_fri_203: ['alan', 'In the photograph Tata was holding a tray. What was on it?'],
  seller_fri_204: ['seller', 'Five kinds, mi amor. All sweet. All mine. Choose with your mouth, not your eyes.'],
  seller_fri_205: ['seller', 'That one? [shrugs] Good for tourists.'],
  seller_fri_206: ['seller', 'Dulce de coco. In the paper, like the old ladies make it. You have a grandmother here, señor?'],
  alan_fri_207: ['alan', 'Somebody does.'],
  alan_fri_look_tray: ['alan', 'Five sweets. I need the one Tata was holding in the photograph.'],
  alan_fri_look_sweet: ['alan', 'A square of dulce de coco in greaseproof paper. Exactly like the photograph. I hope.'],
  alan_fri_look_photo_memory: ['alan', 'The photograph on the shelf in the blue house: Tata with a tray of white squares, each in its own little paper.'],
  alan_fri_look_conde: ['alan', 'El Conde. Every second shop sells something I can\'t afford and every first shop sells it cheaper.'],
  alan_fri_wrong_sweet: ['alan', 'Moncho didn\'t even look up. Wrong sweet. Wrong man. Probably wrong country.'],
  // ================================================================ F3: the palace courtyard, Moncho
  narr_fri_301: ['narr', 'The palace courtyard was cool and clipped and expensive, and the black car stood in the shade with its driver beside it, not looking at anyone.'],
  alan_fri_302: ['alan', 'The bishop\'s up on the gallery. Moncho won\'t say a word while he\'s watching.'],
  alan_fri_look_gallery: ['alan', 'The gallery doors. The bishop goes in to lunch at one. Bishops are punctual about lunch.'],
  alan_fri_303: ['alan', 'I\'ll sit on the bench and look harmless. It\'s my best look.'],
  narr_fri_304: ['narr', 'At one o\'clock exactly the gallery doors opened and closed, and the courtyard was empty except for the car, the driver and the man on the bench.'],
  moncho_fri_305: ['moncho', '[wiping his shoe on the back of his calf] I don\'t talk to tourists.'],
  alan_fri_306: ['alan', 'I brought you something.'],
  narr_fri_307: ['narr', 'Moncho looked at the paper square in Alan\'s hand for a long time. Then he took it, and didn\'t eat it.'],
  moncho_fri_308: ['moncho', 'She made these. Every Sunday. She sold them at the cathedral door so she could buy the paper to wrap them in.'],
  alan_fri_309: ['alan', 'Somebody turned her photograph face down. In the blue house. I turned it back up. I\'m sorry. It wasn\'t mine to touch.'],
  moncho_fri_310: ['moncho', '[flat] Yo la puse así. I put it face down. Because I couldn\'t look at her.'],
  alan_fri_311: ['alan', 'Why not?'],
  moncho_fri_312: ['moncho', 'Because I wasn\'t there. Because the school priest said her drums were the devil\'s, and I was twelve, and I believed him. Because Monseñor gave me this job and this shirt.'],
  moncho_fri_313: ['moncho', '[the shoe again] Monseñor es un hombre bueno. A good man. He buried my mother. He found me work.'],
  moncho_fri_314: ['moncho', '[pause; he flinches] He would not bury her. My grandmother. He said a woman who drums on a beach is not buried from his cathedral. We buried her from the house. Twelve people.'],
  alan_fri_315: ['alan', 'I\'m sorry.'],
  moncho_fri_316: ['moncho', 'Why are you here? Why does a Portuguese bookseller care how an old woman drowned in her bed?'],
  alan_fri_opt_truth: ['alan', '(Tell him about your grandfather.)'],
  alan_fri_opt_book: ['alan', 'I\'m researching the bell. For a book.'],
  alan_fri_opt_police: ['alan', 'The police asked me to help.'],
  moncho_fri_317: ['moncho', '[turns away to the car] Then write your book.'],
  moncho_fri_318: ['moncho', 'Batista? [laughs, not kindly] Batista doesn\'t ask anyone for help. Go away, señor.'],
  alan_fri_319: ['alan', 'My grandfather made bells, in Lisbon. My family made that one, four hundred years ago. He used to sing to me in the shop when I couldn\'t sleep. A song about the sea. I only remember the tune.'],
  alan_fri_320: ['alan', 'He drowned. In the end, everybody in my family has an appointment with the water. I don\'t want to be next. And I don\'t want you to be.'],
  narr_fri_321: ['narr', 'Moncho was quiet. Then, very softly, as if to the car, he began to sing.'],
  moncho_fri_322: ['moncho', '[sung] La campana es del mar, el mar no es de nadie… duérmete, niño, que el mar te sabe el nombre…'],
  narr_fri_323: ['narr', '"The bell is the sea\'s, and the sea is nobody\'s. Sleep, child, the sea knows your name." He stopped in the middle, as if the song had a door in it.'],
  alan_fri_324: ['alan', 'How does it go on?'],
  moncho_fri_325: ['moncho', 'I don\'t know the rest. She wrote the rest down. In a blue exercise book. [pause] I\'m going to burn it.'],
  alan_fri_326: ['alan', 'Moncho, don\'t—'],
  bishop_fri_327: ['bishop', '[from the rail above, pleasant] Have you lost your friends, Señor Sanches? Ramón, the car. We are late for the Nuncio.'],
  narr_fri_328: ['narr', 'Moncho got into the car without a word, and the dulce de coco went with him, still in its paper.'],
  alan_fri_look_moncho: ['alan', 'Moncho. Twenty-four, and wiping his shoes like they\'re the only clean thing he\'s got left.'],
  alan_fri_look_car: ['alan', 'A black Caprice-sized car with diplomatic pretensions. It\'s parked in the shade. The bishop\'s car always gets the shade.'],
  alan_fri_look_fountain_palace: ['alan', 'A fountain in a bishop\'s courtyard. Of course it\'s working. Everything here works except the conscience.'],
  alan_fri_look_bench: ['alan', 'A stone bench, in the shade. A good place to look harmless.'],
  moncho_fri_no_sweet: ['moncho', '[without looking] No.'],
  // ================================================================ F4: Fello turns down a beer
  radio_fri_401: ['radio', '…Hortense, strengthening, east of the Leeward Islands, moving west…'],
  fello_fri_402: ['fello', '[fanning himself with the Listín] Ay, Portugal! A cold one, on the house, for the man who partners me at dominoes! Presidente, so cold it hurts!'],
  fello_fri_403: ['fello', '[to the radio, quieter] David also was going to Puerto Rico. In seventy-nine. And then he turned.'],
  alan_fri_404: ['alan', 'Hoy no, Fello. Not today.'],
  fello_fri_405: ['fello', '[stares; the fan stops] He comes all the way from Europe and he says no to a cerveza. [pause] Ahora sí que tenemos problemas. Now we have problems.'],
  // ================================================================ F5: the fountain, the wall, Vasco
  alan_fri_501: ['alan', 'It\'s four o\'clock and the air is soup. I\'m putting my head under that tap and nobody can stop me.'],
  narr_fri_502: ['narr', 'Alan pulled his shirt over his head and put his head under the fountain\'s tap, and for a whole minute the world was cold and loud and simple.'],
  mireya_fri_503: ['mireya', '[passing, with an armful of towels, not looking] For the towels.'],
  parrot_fri_504: ['parrot', '[a long, low wolf-whistle]'],
  mireya_fri_505: ['mireya', '[passing again, the other way, with the same towels] Still for the towels.'],
  alan_fri_506: ['alan', '[dripping] Vasco said he\'d be on the wall with two beers. I\'ve earned one. I\'ve earned both.'],
  alan_fri_look_tap: ['alan', 'The fountain\'s tap. The coldest thing in the Zona Colonial, apart from the bishop.'],
  narr_fri_507: ['narr', 'The wall over the Ozama was still warm from the day. Vasco sat on it with two bottles of Presidente sweating in his hands, and his face was his own face, not his Church one.'],
  vasco_fri_508: ['vasco', 'One for you. She\'s very sorry. Inês. She won\'t say it, so I\'m saying it for her, which she\'ll also be furious about.'],
  alan_fri_509: ['alan', 'She can be sorry on her own time. [drinks] Vasco. Listen. Moncho sang me something today.'],
  alan_fri_510: ['alan', '[half sung, badly] La campana es del mar, el mar no es de nadie…'],
  narr_fri_511: ['narr', 'Vasco set his beer down very carefully on the stone.'],
  vasco_fri_512: ['vasco', 'Sing it again.'],
  alan_fri_513: ['alan', 'That\'s all he knows. The bell is the sea\'s. The sea is nobody\'s. Why would a song say that?'],
  vasco_fri_514: ['vasco', '[quietly] Porque no es nuestra. Because she isn\'t ours. Tobías\'s worn phrase, Alan. Never sold, never broken, never melted. Because she was given away.'],
  vasco_fri_515: ['vasco', 'In 1586 someone gave that bell to something. And everybody since has been paying the rent.'],
  narr_fri_516: ['narr', 'Across the river El Faro a Colón lit its great cross on the clouds, and under it, district by district, the barrios went dark.'],
  alan_fri_517: ['alan', 'Every night the lighthouse comes on and the power goes off. It\'s like a joke nobody finds funny.'],
  vasco_fri_518: ['vasco', 'Batista rang the hostal. He wants to buy us dinner. A policeman buying dinner is either a bribe or a confession.'],
  alan_fri_look_lighthouse: ['alan', 'El Faro a Colón. They built a lighthouse the size of a cathedral and it lights the clouds instead of the sea.'],
  alan_fri_look_river: ['alan', 'The Ozama, going out to sea like it has somewhere better to be.'],
  alan_fri_look_cannon: ['alan', 'An old cannon, pointing at the river. In 1586 it pointed at Drake. It didn\'t help.'],
  vasco_fri_wall_talk: ['vasco', 'Drink your beer. Then dinner with a policeman. My mother would be so proud.'],
  // ================================================================ F6: Batista at dinner
  narr_fri_601: ['narr', 'Batista ate as if somebody might take the plate away, and talked as if he had decided to before he sat down.'],
  batista_fri_602: ['batista', 'Sea water. In his lungs. Sand. And a fish, this big, in his throat. Don Eusebio drowned in the sea, standing in a park.'],
  batista_fri_603: ['batista', 'Five since April. Not four, like the newspaper says. Five. I count things.'],
  alan_fri_604: ['alan', 'Who?'],
  batista_fri_605: ['batista', '[counting on his fingers] April, Doña Tata, San Antón, in her bed. June, Chago Mercedes, the ferryman, at the river mouth, in his hammock.'],
  batista_fri_606: ['batista', 'July, Doña Luz, who sold candles at the cathedral door, in her chair. August, Pupo, the old shoeshine, on his own step on Las Damas. Today, the watchman, by the fountain.'],
  batista_fri_607: ['batista', 'All dry places. All wet people. The medical examiner says "drowning, accidental". I say five accidents in one neighbourhood is not an accident.'],
  ines_fri_608: ['ines', 'Who were they? To each other?'],
  batista_fri_609: ['batista', 'Old people from the Zona. That\'s all I have. That\'s all the file has.'],
  alan_fri_610: ['alan', '[half to himself] The Sea strikes first at whoever understands the lock.'],
  batista_fri_611: ['batista', '[stops chewing] Say that again.'],
  alan_fri_612: ['alan', 'Something I learned in Lisbon. The Sea strikes first at whoever understands the lock. The people who know how it\'s held back go first.'],
  narr_fri_613: ['narr', 'Batista took the notebook out of his breast pocket and wrote it down, slowly, all of it, and underlined "first".'],
  vasco_fri_614: ['vasco', '[quietly, to Alan] You realise you just told a policeman the ocean is a murderer.'],
  alan_fri_615: ['alan', 'He wrote it down. That\'s more than anyone in Lisbon did.'],
  batista_fri_616: ['batista', '[stands, leaves money under the plate] If you know something, you call me. Not the newspaper. Not the bishop. Me. [the toothpick] And you\'re not surprised by any of this. I noticed.'],
  alan_fri_617: ['alan', 'I\'ll mark them on the map. The five places. In the notebook.'],
  alan_fri_618: ['alan', 'Tata in San Antón. Chago at the river mouth. Doña Luz at the cathedral door. Pupo on Las Damas. The watchman by the fountain.'],
  ines_fri_619: ['ines', 'Now put your wet streets on it. Both of them.'],
  alan_fri_620: ['alan', 'Every death is within a street of a wet band. And every band ends at the foot of the tower. It\'s not five accidents. It\'s a map with a centre.'],
  ines_fri_621: ['ines', '[pause] That\'s very good work, Alan.'],
  alan_fri_622: ['alan', '[surprised, then not showing it] I know.'],
  alan_fri_need_overlay: ['alan', 'The pins are in. Now the two wet bands. I should put them together in the notebook.'],
  // ================================================================ F7: the roof
  narr_fri_701: ['narr', 'On the roof Inês was smoking, which she never did, badly, which she never did either.'],
  alan_fri_702: ['alan', 'Since when do you smoke?'],
  ines_fri_703: ['ines', 'Since about nine o\'clock tonight. It\'s horrible. Here.'],
  narr_fri_704: ['narr', 'They passed the cigarette back and forth. Out beyond the lights of the Malecón, just past the white line of the reef, there was a place where the moon didn\'t reach the water.'],
  alan_fri_705: ['alan', 'Do you see it?'],
  ines_fri_706: ['ines', 'The dark patch. It was two miles out on Wednesday. Tobías said so. [pause] It\'s at the reef now.'],
  ines_fri_707: ['ines', '[very calm, which means she isn\'t] I\'m frightened, Alan.'],
  narr_fri_708: ['narr', 'Nothing more. The jealousy, the archive chair, the thing she had said on Thursday, all of it could wait. She put her head on his shoulder and he let her.'],
  alan_fri_709: ['alan', 'Me too. [pause] This is the worst cigarette I have ever had.'],
  ines_fri_710: ['ines', 'I bought the cheapest. I didn\'t want to enjoy it.'],
  alan_fri_look_patch: ['alan', 'The dark patch, just beyond the reef. It\'s moving against the swell. Water doesn\'t do that.'],
  alan_fri_look_tower_roof: ['alan', 'The cathedral tower. Tobías is up there now, drying her. Every night, like a child.'],
  ines_fri_roof_talk: ['ines', '[looking at the sea] Stay a minute.'],
  // ================================================================ Friday: looks, notes, hints
  alan_fri_look_patch_fri: ['alan', 'The dark patch. At the reef.'],
  parrot_fri_01: ['parrot', '[in Mireya\'s voice] ¡El mapa! ¡El mapa!'],
  mireya_fri_hint_01: ['mireya', '[from the kitchen] The chart, señor. Today\'s pin. Then the park. Then you can do what you like.'],
  parrot_fri_02: ['parrot', '¡Usted lo vio! ¡Usted lo vio!'],
  mireya_fri_hint_02: ['mireya', '[from the kitchen] The sergeant in the park wants you to tell him what you see, señor. Look at the man, and the water, and the stones.'],
  parrot_fri_03: ['parrot', '¡Dulce de coco! ¡Coco!'],
  mireya_fri_hint_03: ['mireya', '[from the kitchen] That boy won\'t talk to you with empty hands. Tata\'s photo, señor: what was on her tray? El Conde sells everything.'],
  parrot_fri_04: ['parrot', '¡A la una! ¡A la una!'],
  mireya_fri_hint_04: ['mireya', '[from the kitchen] Moncho is at the palace with the car. The bishop eats at one. Wait until he goes in, then give the boy your sweet.'],
  parrot_fri_05: ['parrot', '¡Presidente! ¡Fría!'],
  mireya_fri_hint_05: ['mireya', '[from the kitchen] Your Vasco is on the wall with two beers, señor. Cool your head first, you look boiled.'],
  parrot_fri_06: ['parrot', '¡Cinco! ¡Cinco!'],
  mireya_fri_hint_06: ['mireya', '[from the kitchen] Your notebook, señor. Put the sergeant\'s five on the map, and the wet streets with them. Then come up on the roof, the señorita is up there with the cigarettes.'],
  mireya_fri_hint_07: ['mireya', '[from the kitchen] Go up on the roof, señor. She is waiting and pretending not to.'],
  // ================================================================ SATURDAY: S1 breakfast
  narr_sat_101: ['narr', 'Saturday. The radio had been on since five. Señora Mireya had made twice as much mangú, which in her house meant fear.'],
  radio_sat_102: ['radio', '…Hortense is now a hurricane. Categoría uno. Por ahora. For now…'],
  mireya_sat_103: ['mireya', '"For now." I hate the radio when it\'s honest.'],
  narr_sat_104: ['narr', 'Inês came down and sat one chair away from Alan, not two, and said good morning to him, not to the table.'],
  ines_sat_105: ['ines', 'Good morning, Alan.'],
  alan_sat_106: ['alan', 'Good morning. [pause] You\'re never careful.'],
  ines_sat_107: ['ines', '[at the same moment] You\'re never careful.'],
  vasco_sat_108: ['vasco', '[into his coffee] Thank God. They\'re speaking. In unison, but speaking.'],
  ines_sat_109: ['ines', 'So. The day. I take the archive: who stopped the shore in 1930, because somebody did. And tonight the bishop\'s dinner, as Señora Teles.'],
  alan_sat_110: ['alan', 'And I take the streets. Fello says there\'s a woman at the market who knew Tata. Manman Yolande.'],
  vasco_sat_111: ['vasco', 'And I take the soup. Somebody has to.'],
  alan_sat_look_mangu: ['alan', 'Twice the mangú. In this house that\'s a weather report.'],
  // ================================================================ S2: the rum
  fello_sat_201: ['fello', 'Manman Yolande? Ay, Portugal. You don\'t go to Manman Yolande with your hands in your pockets. You bring rum. Good rum. Barceló Imperial.'],
  fello_sat_202: ['fello', 'Not that one! That one is for cleaning engines! For Manman, Imperial! Behind the counter, where the good things live.'],
  alan_sat_203: ['alan', 'How much?'],
  fello_sat_204: ['fello', '[names a price, roars] Don\'t cry. I\'m Dominican, I can do anything by mañana, but I can\'t make Imperial cheap.'],
  alan_sat_205: ['alan', 'I haven\'t got that in pesos. I\'ve got… dollars. Emergency dollars.'],
  fello_sat_206: ['fello', '[the gold tooth flashes] Dollars! At the tourist rate! Aquí todo el mundo es turista, Portugal. Everybody is a tourist here, even me, on Sundays.'],
  fello_sat_207: ['fello', 'One bottle of Imperial for the man from Europe. Tell Manman Fello sent you. She\'ll laugh at you anyway.'],
  alan_sat_look_shelf: ['alan', 'Fello\'s shelf. Four bottles of rum, ranging from "lighter fluid" to "lighter fluid with a nice label".'],
  alan_sat_cheap_rum: ['alan', '[reaching for the cheapest] This one?'],
  alan_sat_look_counter: ['alan', 'Behind the counter, a bottle of Barceló Imperial, on its own, like a saint in a niche.'],
  alan_sat_no_pesos: ['alan', 'I\'d need to rob the bank to pay that in pesos. Mine\'s a very small bank.'],
  alan_sat_look_dollars: ['alan', 'Forty American dollars, folded in the back of my passport. My mother\'s idea. My mother is always right, eventually.'],
  alan_sat_look_rum: ['alan', 'Barceló Imperial. Too good for me. Just right for Manman Yolande, apparently.'],
  fello_sat_talk_again: ['fello', 'Go! Manman is at the Mercado, the candle aisle! Before she sells out of saints!'],
  // ================================================================ S3: the candle aisle, Yolande
  narr_sat_301: ['narr', 'The Mercado Modelo was a cathedral of sacks and baskets. At the back, past the herbs, an aisle went dark and narrow, lit by a thousand glass candles printed with saints.'],
  alan_sat_look_hall: ['alan', 'Everything the island grows, carves or prays to, under one roof. And a drain grating in the floor, for when it rains. It hasn\'t rained.'],
  alan_sat_look_grating_hall: ['alan', 'The grating\'s dry. Good. Let\'s keep it that way.'],
  alan_sat_look_candles: ['alan', 'Saints on candles. Saint Michael with his sword, Saint Barbara with her tower, and a lot of saints I\'ve never been introduced to.'],
  alan_sat_look_bottles: ['alan', 'Bottles of something called Amarra Hombre. "Tie up your man." Vasco would want three.'],
  alan_sat_look_flags: ['alan', 'Sequinned flags hung like laundry. Every one of them catches the candlelight differently. Someone sewed every sequin by hand.'],
  alan_sat_look_sign: ['alan', 'A painted board over the stall: MANMAN YOLANDE — TOUT BAGAY. Everything. Literally.'],
  alan_sat_look_grating: ['alan', 'A drain grating in the floor of the aisle. There\'s a cold breath coming out of it. Like a well that\'s never been opened.'],
  alan_sat_look_yolande: ['alan', 'A big woman in a white headwrap and a dozen necklaces, counting coins without looking at them. She\'s already laughing at me and I haven\'t said anything.'],
  yolande_sat_302: ['yolande', '[without looking up] Blan. You came to the wrong aisle. The tourist saints are by the door.'],
  alan_sat_303: ['alan', 'Fello sent me. With this.'],
  yolande_sat_304: ['yolande', '[looks at the bottle, then at him] Fello. Ha! Fello sends me a blan with a bottle. Put it on the counter. What do you want?'],
  alan_sat_opt_tourist: ['alan', 'I\'m just interested in local religion.'],
  alan_sat_opt_writer: ['alan', 'I\'m writing a book about the cathedral.'],
  alan_sat_opt_truth: ['alan', 'My family made the bell. The one in the Primada.'],
  yolande_sat_305: ['yolande', '[the huge laugh] Interested! Everybody is interested. Go and be interested by the door.'],
  yolande_sat_306: ['yolande', 'A book. [counts coins] Books. Write that I said no.'],
  narr_sat_307: ['narr', 'Yolande stopped counting. She took Alan\'s wrist in her big warm hand, turned it over, and touched her tongue to the inside of it.'],
  yolande_sat_308: ['yolande', '[slowly] Sèl. Salt. Lanmè konnen w. The sea knows you, blan.'],
  yolande_sat_309: ['yolande', 'Tata said one would come. The bell\'s blood. [pause] She didn\'t say he would be so skinny.'],
  alan_sat_need_rum: ['alan', 'I\'m not going to Manman Yolande empty-handed. Fello made that very clear, very loudly.'],
  // ================================================================ S4: the drain (Sea grip)
  narr_sat_401: ['narr', 'Then the candles bent. All of them, the same way, towards the floor. The grating at Alan\'s feet breathed out cold, and black water came up through it like something remembering the way.'],
  alan_sat_402: ['alan', 'I can\'t move. I can\'t— my feet—'],
  narr_sat_403: ['narr', 'The water was at his ankles. His knees. It was cold the way only very deep things are cold, and it pulled. Alan could hear his own heart: three beats, and a rest, and the third came late.'],
  yolande_sat_404: ['yolande', '[reaching, slow, for the counter] Blan. Look at me. Look at what is near my hand.'],
  alan_sat_grip_struggle: ['alan', '[pulling at his own legs] Come on— come ON—'],
  narr_sat_grip_struggle: ['narr', 'The more he fought, the higher it came. Fear is what it eats.'],
  alan_sat_grip_breath: ['alan', '[holds his breath]'],
  narr_sat_grip_breath: ['narr', 'Holding his breath only made the water patient.'],
  alan_sat_grip_vasco: ['alan', 'Vasco! VASCO!'],
  narr_sat_grip_vasco: ['narr', 'Vasco was across the city, eating soup. Nobody came.'],
  alan_sat_405: ['alan', '[eyes on the bottle] Yolande! The rum!'],
  narr_sat_406: ['narr', 'Yolande\'s hand closed on the Barceló. She took a mouthful, and sprayed it full in Alan\'s face and over the water.'],
  narr_sat_407: ['narr', 'The water went back down the grating as if somebody had called it home. The candles stood up straight.'],
  yolande_sat_408: ['yolande', '[wiping her mouth] Rum turns it back. For a moment. Only a moment, blan. Remember that.'],
  alan_sat_409: ['alan', '[gasping, soaked] It came for me. It knew where I was standing.'],
  yolande_sat_410: ['yolande', 'Of course it knew. You understand the lock. It goes first for those. And it eats fear. You were frightened, so it came up. Next time be less delicious.'],
  yolande_sat_411: ['yolande', 'Come in the back. Now, before it thinks again.'],
  alan_sat_grip_title: ['alan', 'The water is rising. Alan can\'t move. What can somebody else do?'],
  // ================================================================ S5: Yolande's back room
  narr_sat_501: ['narr', 'Behind the curtain it smelled of rum and candle wax and the sea. On the altar, between the candles, sat a little wooden boat painted blue and white.'],
  yolande_sat_502: ['yolande', 'Sit. Drink. [she drinks first] Tata and me. Forty years. Nobody in San Antón knew. Nobody.'],
  alan_sat_503: ['alan', 'You and Doña Tata? But—'],
  yolande_sat_504: ['yolande', 'But she was Dominican and I am Haitian, and the Dominican ladies cross the street, and the Haitian ladies cross back. Yes. [the huge laugh, and then not] That is why nobody knew.'],
  yolande_sat_505: ['yolande', 'Tata had the drums, and the Spanish salves. I have the Kreyòl songs, and the sign of Agwe, the boat. One without the other is nothing. Half a song. Half a sign. It needs both halves, blan. Both.'],
  alan_sat_506: ['alan', 'Both halves. The Dominican side and the Haitian side.'],
  yolande_sat_507: ['yolande', 'And only Tata knew the rock. The place on the beach. She led. We followed the light. Now she\'s dead, and nobody knows where to stand.'],
  alan_sat_508: ['alan', 'Followed the light. What light?'],
  yolande_sat_509: ['yolande', '[shrugs] She looked at the tower and she walked. I followed her back. Ask the bell.'],
  yolande_sat_510: ['yolande', 'In ninety-one they took half my street to the border. The colonel with the list, el coronel de la lista. Heavy man. Nice suit. Hands in his pockets.'],
  alan_sat_511: ['alan', 'I saw him. This morning— yesterday. At the watchman.'],
  yolande_sat_512: ['yolande', 'Then he is back. [pause] Watch your hands, blan. He likes lists.'],
  alan_sat_look_boat: ['alan', 'A little wooden boat on the altar, blue and white. Somebody carved it for somebody they loved.'],
  alan_sat_look_altar: ['alan', 'Candles, rum, a boat, a saint I half recognise. It feels less like a church than like somebody\'s kitchen table. In a good way.'],
  yolande_sat_talk_again: ['yolande', 'Two bottles next time, blan. One for when the sea comes. One for me.'],
  // ================================================================ S6: the vèvè
  narr_sat_601: ['narr', 'Yolande poured a line of rum onto the floor and drew with it, fast, her big hand sure: a boat, a mast, a sail, a little flag; waves under it; crosses; stars.'],
  yolande_sat_602: ['yolande', 'Agwe\'s boat. The sign. Look, blan. Look hard. I\'m not drawing it twice.'],
  narr_sat_603: ['narr', 'Then she rubbed it out with her bare foot.'],
  yolande_sat_604: ['yolande', 'Now draw it in your little book. From your head. Your head is the only place it is now.'],
  alan_sat_605: ['alan', 'I\'ve seen this. On Tata\'s floor, in the blue house. In chalk. Half washed away.'],
  yolande_sat_606: ['yolande', 'Of course you have. [taps the notebook] Keep that. You will need it on the night.'],
  yolande_sat_607: ['yolande', '[looks at the drawing, unimpressed] Hm. Good enough to remember. Not good enough to dance on. Again, if you want.'],
  yolande_sat_608: ['yolande', '[looks a long time] Hm. Tata would have said: the blan has hands.'],
  alan_sat_veve_q: ['alan', 'What came next in her drawing?'],
  alan_sat_look_sketch: ['alan', 'My sketch of Agwe\'s boat, in pencil. Yolande drew it in rum in about four seconds. Mine took twenty minutes and has an eraser hole.'],
  alan_sat_609: ['alan', 'Yolande. Will you come? When it\'s time? To the shore?'],
  yolande_sat_610: ['yolande', '[the laugh, short] Ask me when you know where the rock is, blan. And when you have the other half of the song. Then ask me.'],
  narr_sat_611: ['narr', 'Across the city, at the same hour, Inês was being shown into a reading room with exactly two chairs.'],
  // ================================================================ S7: Inês, the 1930 trail
  narr_sat_701: ['narr', 'The cathedral archive smelled of paper, mould and Padre Ulises\'s cologne. He held up two fingers before she had said a word.'],
  ulises_sat_702: ['ulises', 'Dos. Two chairs. Gloves. Always gloves. And the year, señora?'],
  ines_sat_703: ['ines', 'Nineteen thirty. The hurricane. Somebody stopped a gathering on the shore that year, and I want to know who asked them to.'],
  ulises_sat_704: ['ulises', '[delighted, hiding it] Nobody asks about 1930. They ask about Columbus. Gloves.'],
  ines_sat_look_acts: ['ines', 'The chapter acts for 1930. Bound, indexed, beautiful.'],
  ines_sat_acts_read: ['ines', 'Money, Masses, the price of candles, a new organ. Not one word about a hurricane that flattened the city. That isn\'t forgetting. That\'s tidying.'],
  ines_sat_look_folder: ['ines', 'The archive\'s own folder for 1930. Odds and ends somebody didn\'t want to throw away.'],
  ines_sat_folder_read: ['ines', 'A photograph of a radio-station plaque: "San Zenón, 3 de septiembre de 1930". So the gathering on the shore would have been that week. Whatever happened, happened then.'],
  ines_sat_look_index: ['ines', 'The card index of correspondence received. Padre Ulises\'s predecessor had beautiful handwriting and strange ideas.'],
  ines_sat_index_g: ['ines', 'Nothing under G for Guardia Nacional. Nothing under G at all except "Gregorian chant, cassettes". Wonderful.'],
  ines_sat_look_colombina: ['ines', 'A card on the desk: "Sociedad Colombina" — filed under C. Not S. He filed by the last word.'],
  ines_sat_index_title: ['ines', 'The Guardia Nacional\'s letter. Under which letter?'],
  ines_sat_index_n: ['ines', 'Under N. "Guardia Nacional". He filed by the last word. And here it is: a letter of 6 September 1930.'],
  ines_sat_index_wrong: ['ines', 'Nothing. Think like a man who files by the last word, Inês.'],
  ines_sat_letter_read: ['ines', '"Eleven persons detained. Drums confiscated." And in pencil, in the margin, in another hand: "Gracias a Dios." [pause] It says "in answer to your request of the 28th ultimo". Somebody asked.'],
  ines_sat_look_copybooks: ['ines', 'The cathedral\'s outgoing copybooks. Carbons of every letter it ever sent.'],
  ines_sat_copybooks_early: ['ines', 'Outgoing letters. Thousands of them. I need a date before I start, or I\'ll be here until the next hurricane.'],
  ines_sat_carbon_read: ['ines', 'August 1930. The twenty-eighth. The Archbishop\'s secretary to the Guardia Nacional: "to disperse the superstitious gathering on the shore". [pause] The Church asked. The Church asked for the drums to be taken.'],
  ines_sat_705: ['ines', 'Vasco asked me on Thursday who asked them to. Now I can tell him.'],
  ulises_sat_706: ['ulises', '[reading over her shoulder, very quiet] I will make you a copy. [pause] I will make you two.'],
  ulises_sat_talk: ['ulises', 'Gloves, señora. And whisper. The documents are sleeping.'],
  ines_sat_look_ulises: ['ines', 'Padre Ulises. Exact, territorial, and pretending very hard not to enjoy this.'],
  ines_sat_look_chairs: ['ines', 'Two chairs. One for me, one for him. Alan would have to stand. Alan would like that less than I do.'],
  ines_sat_trail_done: ['ines', 'The letter and the carbon, copied. Now the dinner. I have to become Señora Teles in an hour, and I haven\'t got the shoes for it.'],
  // ================================================================ S8: the bishop's dinner
  narr_sat_801: ['narr', 'The bishop\'s dining room was candles and dark wood and silver, and the soup was sancocho, and every canon at the table was looking at Inês\'s left hand.'],
  bishop_sat_802: ['bishop', '[warm, polished] Señora Teles. Welcome. You have been in our archive all day, I hear. Padre Ulises is in love. He gave you two chairs.'],
  canon_sat_803: ['canon', '[leaning in] And how did you meet our Doctor Teles, señora?'],
  ines_sat_teles_q1: ['ines', '"How did you meet?"'],
  ines_sat_a1_church: ['ines', 'Through the Church. He was a gift from the Church in Lisbon. To me, I mean.'],
  ines_sat_a1_work: ['ines', 'At work. I\'m his assistant. I was his assistant first, and then his wife.'],
  ines_sat_a1_party: ['ines', 'At a party. In Paris. There was a lot of champagne.'],
  secretary_sat_804: ['secretary', '[sweating, delighted] Ah, a working marriage. Sì. The best kind. Like Saint Joseph and the carpentry.'],
  secretary_sat_805: ['secretary', '[a small frown] Paris? But the monsignor said you were his assistant. From Lisbon.'],
  canon_sat_806: ['canon', 'And children, señora? God willing?'],
  ines_sat_teles_q2: ['ines', '"Children?"'],
  ines_sat_a2_three: ['ines', 'Three. All boys. All in the seminary.'],
  ines_sat_a2_notyet: ['ines', 'Not yet. We work too much. The bells always come first.'],
  ines_sat_a2_none: ['ines', 'None. We don\'t— I mean, we can\'t. I mean, no.'],
  secretary_sat_807: ['secretary', 'Ah, the bells first. A true vocation. Eccellenza, did you hear? A vocation.'],
  canon_sat_808: ['canon', '[very interested] Three boys in the seminary, and you so young.'],
  canon_sat_809: ['canon', '[sly] And does Doctor Teles snore?'],
  ines_sat_teles_q3: ['ines', '"Does he snore?"'],
  ines_sat_a3_snores: ['ines', 'Like a bell-founder\'s bellows. I take notes. For the archive.'],
  ines_sat_a3_dunno: ['ines', 'I wouldn\'t know. We have separate rooms.'],
  ines_sat_a3_angel: ['ines', 'Never. He sleeps like an angel. On his back. With his hands folded.'],
  vasco_sat_810: ['vasco', '[blushing into the sancocho] Inês.'],
  secretary_sat_811: ['secretary', '[laughing despite himself] For the archive! Eccellenza, I bless this marriage. Officially. In the name of the Nunciature.'],
  secretary_sat_812: ['secretary', '[watching her, the smile gone careful] Separate rooms. Hm.'],
  ines_sat_813: ['ines', '[interior] Three straight answers and a monsignor has blessed a marriage that doesn\'t exist. Vasco will never recover.'],
  ines_sat_814: ['ines', '[interior] He\'s watching me now. Fine. I\'ve been watched by worse. I\'ve been watched by Alan doing the accounts.'],
  narr_sat_815: ['narr', 'Under the noise of the soup, the young man from the Ministry of Culture leaned towards Inês as if he were reaching for the bread.'],
  peralta_sat_816: ['peralta', '[whispering] Licenciado Peralta. Patrimonio. I shouldn\'t be telling you this.'],
  ines_sat_opt_permissions: ['ines', 'Who gives permission to take a bell out of a World Heritage cathedral?'],
  ines_sat_opt_soup: ['ines', 'The soup is very good.'],
  peralta_sat_817: ['peralta', 'The soup is excellent. That\'s not what I shouldn\'t be telling you.'],
  peralta_sat_818: ['peralta', '[whispering faster] The Zona was inscribed in 1990. UNESCO. "Significant alterations to be notified." To Paris. A bell is an alteration. [pause] The Church notifies God, and God has not yet objected.'],
  ines_sat_819: ['ines', 'Paris. A dossier to Paris. Thank you, Licenciado.'],
  peralta_sat_820: ['peralta', 'I didn\'t say anything. I was asking for the salt.'],
  narr_sat_821: ['narr', 'Then the bishop set down his spoon, and the table went quiet, because it always did when he set down his spoon.'],
  bishop_sat_822: ['bishop', 'My grandmother lived in Gualey, by the river. She kept the misterios. Candles under the bed, a glass of water for the dead, rum for Saint Michael. She was the kindest woman I have ever known.'],
  bishop_sat_823: ['bishop', 'And she was afraid every day of her life. Of the sea, of the dead, of a hundred saints who wanted feeding. I will not have my people afraid. I will give them a new bell, a modern bell, and something that is ours, not theirs.'],
  ines_sat_824: ['ines', '[interior] He means it. And he\'s going to destroy them all.'],
  bishop_sat_825: ['bishop', '[turning the ring on his finger] And your friend, señora. Señor Sanches. I hear he spends his days in San Antón, with drummers. And his nights…'],
  ines_sat_def_title: ['ines', 'Defend Alan. How?'],
  ines_sat_def_dry: ['ines', 'Señor Sanches is a bookseller. Curiosity is a professional deformity. Like gout, for canons.'],
  ines_sat_def_fierce: ['ines', 'Señor Sanches is the bravest man at this table, Excellency, and the only one who has been to San Antón this year.'],
  ines_sat_def_funny: ['ines', 'His nights are none of my business, Excellency. His days are a disaster. That\'s what I\'m for.'],
  bishop_sat_826: ['bishop', '[the smile that stops at the eyes] Of course. Forgive me. More sancocho.'],
  ines_sat_look_card: ['ines', 'My place card. "Sra. Teles". Closed with a seal of purple wax pressed with the palace crest. Very grand. Very useful, possibly.'],
  ines_sat_take_card: ['ines', '[slips it into her bag] A souvenir. Every wife keeps the place card.'],
  ines_sat_take_card_first: ['ines', 'Let me look at it properly first. I don\'t steal what I haven\'t read.'],
  ines_sat_look_candles_d: ['ines', 'Three candelabra. Enough wax to light the reading room for a year.'],
  ines_sat_look_paintings: ['ines', 'Saints, in gold frames, looking down at the soup.'],
  ines_sat_look_bishop: ['ines', 'The bishop. A warm, practised smile that stops at the eyes.'],
  ines_sat_look_secretary: ['ines', 'The Nuncio\'s secretary. Plump, damp, immaculate black, and he says "sì" when he means "God help me".'],
  ines_sat_look_peralta: ['ines', 'A young man in a suit too big for him, from the Ministry of Culture. He looks like he wants to tell me something and is afraid of the soup.'],
  ines_sat_look_vasco_d: ['ines', 'Vasco, my husband for the evening, being very good, very red, and very Catholic.'],
  vasco_sat_dinner_talk: ['vasco', '[through his teeth] Smile. You\'re my wife. You adore me.'],
  ines_sat_827: ['ines', '[to Vasco, leaving] Go and find Alan. He\'ll be in the kind of bar you two like. Tell him the Church asked. Tell him I said so.'],
  vasco_sat_828: ['vasco', 'Señora Teles. [kisses her hand] Thank you for a wonderful marriage.'],
  ines_sat_leave_early: ['ines', 'I can\'t leave yet. I haven\'t finished being Señora Teles.'],
  // ================================================================ S9: Moncho at the fountain
  narr_sat_901: ['narr', 'It was nearly midnight when Inês came back to the hostal. The street door was open, and somebody was sitting on the edge of the fountain with a blue exercise book on his knees.'],
  moncho_sat_902: ['moncho', '[not looking up] No la quemé. I didn\'t burn it. I lit the match. I couldn\'t.'],
  moncho_sat_903: ['moncho', 'There was water in her house all night. On the floor. Wall to wall. Salt. I sat in it with the matches and I couldn\'t.'],
  ines_sat_904: ['ines', 'My father mended nets. In Peniche. Every winter somebody didn\'t come back, and every spring he mended the nets anyway.'],
  narr_sat_905: ['narr', 'Moncho moved over on the edge of the fountain. She sat. He opened the book. They read.'],
  // ================================================================ S10: Yunior, El Conde, the blue door
  narr_sat_1001: ['narr', 'El Conde at night was louder than El Conde by day, and Alan, damp and smelling of rum, did not fit into any of it.'],
  yunior_sat_1002: ['yunior', '[taking his arm] Ay, papi. You look like you\'ve seen a muerto. Portugal, what happened to you?'],
  alan_sat_1003: ['alan', 'A drain. Long story. I need a bar where a man called Lalo pours drinks for drummers.'],
  yunior_sat_1004: ['yunior', 'Lalo\'s! The blue door! I know it. Everybody knows it. Nobody tells tourists.'],
  yunior_sat_1005: ['yunior', '[looking at the linen jacket over Alan\'s arm] But my memory is very bad tonight, papi. Very bad. Unless I am wearing something nice.'],
  alan_sat_1006: ['alan', 'You\'ve been looking at this jacket since Thursday.'],
  yunior_sat_1007: ['yunior', 'Since Thursday! He noticed! [puts it on; it\'s too big; he looks wonderful] Ay, mi pana. What a mess you are. Come. The blue door.'],
  alan_sat_look_yunior: ['alan', 'Yunior. Twenty, quick, and his professional grin and his real grin are fighting for the same face.'],
  yunior_sat_no_jacket: ['yunior', 'My memory, papi. It needs a jacket.'],
  alan_sat_look_jacket: ['alan', 'My linen jacket. Crumpled, a bit damp, and now apparently currency.'],
  yunior_sat_talk_again: ['yunior', '[twirling in the jacket] The blue door, papi! Ciudad Nueva! Tell Lalo Yunior sent you, he\'ll charge you double.'],
  // ================================================================ S11: Lalo and the perm sisters
  narr_sat_1101: ['narr', 'Behind the blue door the bar was red light and mirrors and a hairdresser\'s chair in the corner, and nobody looked at Alan funny, which in Alan\'s experience was the definition of a good bar.'],
  lalo_sat_1102: ['lalo', '[pouring before he\'s asked] Sit, mi amor. You look like a wet cat. What happened?'],
  alan_sat_1103: ['alan', 'The sea came up through a drain at the market and tried to drown me. A woman called Yolande spat rum at it.'],
  lalo_sat_1104: ['lalo', '[pink nails tapping the bar] And you\'re telling a bartender. Good. Bartenders and hairdressers. We\'re the only confessors left. I\'m both.'],
  alan_sat_1105: ['alan', 'It\'s about Doña Tata. In San Antón.'],
  narr_sat_1106: ['narr', 'The name stopped him with the bottle in the air.'],
  lalo_sat_1107: ['lalo', '[quietly] Yo tocaba para ella. I played for her. On the shore. When I was a boy.'],
  lalo_sat_1108: ['lalo', '[turns his hands over: the calluses] A drummer\'s hands. Under the nail polish. My father found out when I was seventeen. He took his belt to me, and I never touched a drum again.'],
  alan_sat_1109: ['alan', 'Who taught you?'],
  lalo_sat_1110: ['lalo', 'Papá Lilo. The last of the old drummers. Ninety-two, one eye, and he\'s still the best hands on this island. [writes on an order pad] Villa Consuelo. The gallera. Tomorrow. Take him two bottles. You\'ll understand why.'],
  lalo_sat_1111: ['lalo', 'You could get a stone to talk, mi amor.'],
  alan_sat_look_lalo: ['alan', 'Lalo. Pink nails, gold rings, a silk shirt, and a look that has heard everything twice.'],
  alan_sat_look_chair: ['alan', 'A hairdresser\'s chair in a bar. Lalo cuts hair until nine and pours rum after. Both are a kind of honesty.'],
  alan_sat_look_drum: ['alan', 'A drum on the little stage. Nobody\'s playing it. It looks like it\'s waiting for someone in particular.'],
  alan_sat_look_mirror: ['alan', 'A mirror with light bulbs round it. I look like a man who\'s been in a drain. I am a man who\'s been in a drain.'],
  alan_sat_look_sisters: ['alan', 'Two old ladies at the back table with matching perms, matching handbags and a cake tin. On a Saturday night. In a bar.'],
  alan_sat_look_address: ['alan', 'Lalo\'s note: an address in Villa Consuelo, a little map, and a ring from a glass. "The gallera. Ask for Papá Lilo."'],
  ercilia_sat_1112: ['ercilia', '[turning round in her chair] Tata? Did he say Tata? Tata Bran?'],
  alan_sat_1113: ['alan', 'Did you know her?'],
  ercilia_sat_1114: ['ercilia', 'Know her! My mother sang on her shore. Salves, every September, until the guards came. And then nobody asked us. Forty years, and nobody asked.'],
  sisters_sat_1115: ['sisters', '[together] Nobody asked.'],
  alan_sat_1116: ['alan', 'I\'m asking. When it\'s time, will you come down to the shore? And sing?'],
  ercilia_sat_1117: ['ercilia', '[to Lalo, not to Alan] For the shore? I\'ll bring my hermana.'],
  lalo_sat_1118: ['lalo', 'Exacto. That\'s why. [to Alan] You asked Doña Ercilia, not me. Good. You\'re learning.'],
  sisters_sat_1119: ['sisters', 'We\'ll bring cake. For the hurricane.'],
  alan_sat_opt_sisters_ask: ['alan', '(Ask the ladies about Tata.)'],
  lalo_sat_talk_again: ['lalo', 'Drink, mi amor. The night is long and you\'re very damp.'],
  // ================================================================ S12: Vasco arrives, the bachata
  vasco_sat_1201: ['vasco', '[at the door, in his dinner jacket] She sent me. She said "the kind of bar you two like". I think it was a compliment.'],
  alan_sat_1202: ['alan', 'How was the soup, Doctor Teles?'],
  vasco_sat_1203: ['vasco', 'I am married. Officially. The Nunciature blessed it. Inês was magnificent. I may never eat sancocho again.'],
  narr_sat_1204: ['narr', 'The band started a bachata, and Alan held out his hand, because Alan always led.'],
  alan_sat_1205: ['alan', 'Dance with me. I\'ll lead.'],
  vasco_sat_1206: ['vasco', 'I don\'t know how. I was in a seminary.'],
  narr_sat_1207: ['narr', 'For one bar Vasco trod on Alan\'s shoes. Then something happened to his hips, and he was leading, beautifully, and Alan was following and trying not to look surprised.'],
  alan_sat_1208: ['alan', '"I don\'t know how."'],
  vasco_sat_1209: ['vasco', 'The seminary had a very good choir and a very bad Friday night policy. [mid-turn, murmuring] Nove. Behind you. Don\'t look.'],
  narr_sat_1210: ['narr', 'Alan looked. At the end of the bar a man with a trumpet case and an easy smile was watching them dance, in no hurry at all.'],
  alan_sat_1211: ['alan', '[turning back] Nove. Generous.'],
  vasco_sat_1212: ['vasco', 'News, while we dance. Inês found a carbon. The Church asked the Guardia to break up the shore in 1930. "Gracias a Dios," in pencil.'],
  vasco_sat_1213: ['vasco', 'And the bishop asked about you. She defended you. The way you put a hand out when somebody falls.'],
  vasco_sat_1213_dry: ['vasco', 'She said curiosity is your professional deformity. Like gout, for canons. Two of the canons have gout.'],
  vasco_sat_1213_fierce: ['vasco', 'She said you were the bravest man at the table. You weren\'t at the table. The bishop noticed that.'],
  vasco_sat_1213_funny: ['vasco', 'She said your days are a disaster, and that\'s what she\'s for. The secretary laughed so hard he blessed us again.'],
  alan_sat_1214: ['alan', '[quiet] She said that.'],
  vasco_sat_1215: ['vasco', 'It\'s going to be awful. And then it\'s going to be fine.'],
  alan_sat_look_dance: ['alan', 'Sway the hips, follow the hand. For once in my life I\'m not leading. It\'s restful.'],
  alan_sat_dance_title: ['alan', 'The bachata. Follow Vasco\'s lead.'],
  alan_sat_dance_lead: ['alan', '(Try to lead.)'],
  alan_sat_dance_follow: ['alan', '(Follow the sway.)'],
  vasco_sat_dance_lead: ['vasco', '[treading on his feet, gently, on purpose] No. Follow.'],
  // ================================================================ S13: Darío, optional
  dario_sat_1301: ['dario', '[sliding along the bar, easy] You two dance like you\'ve done it before. I play six nights a week. I\'ve got a roof, and a cassette, and nowhere to be.'],
  vasco_sat_1302: ['vasco', '[wicked and patient, to Alan] He\'s got a roof.'],
  alan_sat_opt_dario_yes: ['alan', '(Go up to the roof with Darío and Vasco.)'],
  alan_sat_opt_dario_no: ['alan', '(Thank him, and walk home along the wall with Vasco.)'],
  narr_sat_1303: ['narr', 'A roof in Ciudad Nueva. Stars over the dark barrios, El Faro\'s cross on the clouds, a slow cassette, two bottles on the parapet.'],
  vasco_sat_1304: ['vasco', '[mouthing it to Alan, over Darío\'s shoulder] Ainda não.'],
  narr_sat_1305: ['narr', 'What happened on the roof stayed on the roof.'],
  narr_sat_1306: ['narr', 'At dawn Darío stood at the parapet and played them out with a slow bolero, the trumpet very soft, so as not to wake Ciudad Nueva.'],
  dario_sat_1307: ['dario', 'My band rehearses at Lalo\'s on Monday afternoons. If you need a trumpet. For anything.'],
  narr_sat_1308: ['narr', 'They walked home along the wall, Alan with his shirt over his shoulder, Vasco humming the bachata, and the river going out to sea under them, dark as a held breath.'],
  alan_sat_1309: ['alan', 'Nove, you said.'],
  vasco_sat_1310: ['vasco', 'I was being polite. Oito.'],
  alan_sat_look_dario: ['alan', 'Darío. Rumpled, a trumpet case, an easy smile, in no hurry for anything. Vasco gave him a nine. Vasco is a generous marker.'],
  alan_sat_look_cassette: ['alan', 'A cassette player and a tape of slow boleros. The universal instrument of bad decisions made well.'],
  alan_sat_look_mattress: ['alan', 'A mattress under the stars. Very practical. Very Ciudad Nueva.'],
  // ================================================================ S14: dawn at the fountain
  narr_sat_1401: ['narr', 'Five in the morning. The hostal\'s door stood open. Inês was sitting on the edge of the fountain in her dinner dress, barefoot, the blue exercise book open on her knees.'],
  ines_sat_1402: ['ines', 'Moncho brought it. He didn\'t burn it. [pause] Alan, it\'s all here. Sixty years. Names, dates, songs, the rules. In Tata\'s worst handwriting.'],
  ines_sat_1403: ['ines', 'If that bell goes into the furnace on Tuesday, it\'s not one hurricane. It\'s all of them.'],
  parrot_sat_1404: ['parrot', '¡Huracán! ¡Huracán!'],
  vasco_sat_1405: ['vasco', '[sitting down beside her] Then we have three days.'],
  alan_sat_look_notebook_tata: ['alan', 'Tata\'s blue exercise book. Swollen, water-stained, sixty years of a shore in a schoolgirl\'s copybook.'],
  // ================================================================ Saturday: hints
  parrot_sat_01: ['parrot', '¡Imperial! ¡Imperial!'],
  mireya_sat_hint_01: ['mireya', '[from the kitchen] Fello\'s, señor. San Antón. Don\'t go to Manman Yolande with cheap rum. And Fello takes dollars, if you cry a little.'],
  parrot_sat_02: ['parrot', '¡Tout bagay! ¡Tout bagay!'],
  mireya_sat_hint_02: ['mireya', '[from the kitchen] The Mercado Modelo, señor, the candle aisle at the back. Tell her the truth. She can smell the other thing.'],
  parrot_sat_03: ['parrot', '¡El ron! ¡El ron!'],
  mireya_sat_hint_03: ['mireya', '[from the kitchen] When the water comes, señor, you can\'t do anything. Somebody else can. Look at what is near her hand.'],
  parrot_sat_04: ['parrot', '¡Detrás! ¡Detrás!'],
  mireya_sat_hint_04: ['mireya', '[from the kitchen] Go behind her curtain, señor. She will tell you things. Then she will draw, and you must look hard.'],
  parrot_sat_05: ['parrot', '[in Padre Ulises\'s voice] ¡Dos! ¡Guantes!'],
  ines_sat_hint_05: ['mireya', '[somewhere, the parrot again] The 1930 acts are empty on purpose, señorita. Look at the folder for the date, the index for the letter. That old priest filed by the last word.'],
  ines_sat_hint_06: ['mireya', '[the parrot, in Vasco\'s voice] The letter answers a request. The copybooks have the carbons. A date, señorita: the 28th.'],
  parrot_sat_07: ['parrot', '¡Señora Teles! ¡Señora Teles!'],
  ines_sat_hint_07: ['mireya', '[the parrot, very pleased] The bishop wrote "your assistant". Vasco wrote "a gift from the Church in Lisbon". Be both, señorita. Wife and assistant. And keep the pretty seal.'],
  parrot_sat_08: ['parrot', '¡La chaqueta! ¡La chaqueta!'],
  mireya_sat_hint_08: ['mireya', '[from the kitchen] El Conde, señor. That boy Yunior knows every bar. He has wanted your jacket since Thursday.'],
  parrot_sat_09: ['parrot', '¡Mi amor! ¡Mi amor!'],
  mireya_sat_hint_09: ['mireya', '[from the kitchen] At Lalo\'s, talk about Tata. Then ask the ladies with the cake, not Lalo.'],
  mireya_sat_hint_10: ['mireya', '[from the kitchen] Go home, señor. Or don\'t. But come back before the stairs get loud.'],
});
